insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-117', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'Kohlrausch''s law of independent migration states that $\Lambda_m^\circ$ of an electrolyte is', '["the sum of the limiting ionic conductivities of its cation and anion","equal to the product $\\lambda_+^\\circ \\times \\lambda_-^\\circ$","independent of the identities of the two ions","measurable only for metals, not for salts"]'::jsonb, 0, 'At infinite dilution each ion migrates independently, so $\Lambda_m^\circ = \nu_+\lambda_+^\circ + \nu_-\lambda_-^\circ$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'kohlrausch') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
