insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-119', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'Limiting molar conductivity of a weak electrolyte such as ethanoic acid is obtained by', '["combining $\\Lambda_m^\\circ$ values of suitable strong electrolytes, not by plotting $\\Lambda_m$ versus $\\sqrt{c}$","extrapolating a Kohlrausch $\\sqrt{c}$ graph of the weak acid itself","measuring $\\kappa$ of distilled water alone","equating $\\Lambda_m$ at 1 M to $\\Lambda_m^\\circ$"]'::jsonb, 0, 'A weak acid is far from fully ionised even when dilute, so the $\sqrt{c}$ plot does not give a reliable intercept.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'kohlrausch') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
